function flatToNested(flatObj) {
  const result = {};

  Object.keys(flatObj).forEach((key) => {
    const value = flatObj[key];
    const keys = key.split('.');
    let current = result;

    keys.forEach((k, index) => {
      if (index === keys.length - 1) {
        current[k] = value;
      } else {
        if (!(k in current)) {
          current[k] = {};
        } else if (typeof current[k] !== 'object' || current[k] === null || Array.isArray(current[k])) {
          current[k] = {};
        }
        current = current[k];
      }
    });
  });

  return result;
}

module.exports = { flatToNested };
